import{_ as e,C as r,o as n,c as m,a2 as t,E as o}from"./chunks/framework.BqNd1sPY.js";const L=JSON.parse('{"title":"D01：大模型到底是什么","description":"","frontmatter":{},"headers":[],"relativePath":"01-14天理论课/D01-大模型到底是什么.md","filePath":"01-14天理论课/D01-大模型到底是什么.md"}'),s={name:"01-14天理论课/D01-大模型到底是什么.md"};function k(l,a,d,c,w,h){const i=r("MermaidDiagram");return n(),m("div",null,[a[0]||(a[0]=t('<h1 id="d01-大模型到底是什么" tabindex="-1">D01：大模型到底是什么 <a class="header-anchor" href="#d01-大模型到底是什么" aria-label="Permalink to &quot;D01：大模型到底是什么&quot;">​</a></h1><h2 id="今日目标" tabindex="-1">今日目标 <a class="header-anchor" href="#今日目标" aria-label="Permalink to &quot;今日目标&quot;">​</a></h2><p>能把大语言模型描述为“根据已有 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 预测下一个 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 概率的<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>化模型”，并区分训练和<a href="/LLMTrain/05-速查表/术语速查#term-inference" class="wiki-term" data-wiki-title="inference" data-wiki-summary="使用训练好的参数，根据输入计算预测或生成结果。" data-wiki-misconception="推理阶段通常会继续更新模型权重。">推理</a>。</p><h2 id="先看全流程" tabindex="-1">先看全流程 <a class="header-anchor" href="#先看全流程" aria-label="Permalink to &quot;先看全流程&quot;">​</a></h2>',4)),o(i,{code:"Zmxvd2NoYXJ0IFRECiAgICBBW+aWh+acrF0gLS0+IEJbVG9rZW5pemVyXQogICAgQiAtLT4gQ1t0b2tlbiBJRF0KICAgIEMgLS0+IERbVHJhbnNmb3JtZXJdCiAgICBEIC0tPiBFW+S4i+S4gOS4qiB0b2tlbiDnmoTmpoLnjoddCiAgICBFIC0tPiBGW+mAieaLqeS4gOS4qiB0b2tlbl0KICAgIEYgLS0+fOi/veWKoOWQjue7p+e7rXwgRAo="}),a[1]||(a[1]=t('<h3 id="三个角色" tabindex="-1">三个角色 <a class="header-anchor" href="#三个角色" aria-label="Permalink to &quot;三个角色&quot;">​</a></h3><ul><li><strong><a href="/LLMTrain/05-速查表/术语速查#term-tokenizer" class="wiki-term" data-wiki-title="tokenizer" data-wiki-summary="负责把文本切成 token，并在 token 与整数 ID 之间转换的规则和词表。" data-wiki-misconception="tokenizer 是模型自己临时决定的切词方式。">Tokenizer</a></strong>：把文本切成 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a>，再映射为整数 ID。</li><li><strong>模型<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a></strong>：训练中调整的大量数字。它们共同决定输入经过模型后得到什么 <a href="/LLMTrain/05-速查表/术语速查#term-logits" class="wiki-term" data-wiki-title="logits" data-wiki-summary="softmax 之前的任意实数分数，用来比较各候选 token。" data-wiki-misconception="logits 已经是概率或正确率。">logits</a>。</li><li><strong>生成策略</strong>：把 <a href="/LLMTrain/05-速查表/术语速查#term-logits" class="wiki-term" data-wiki-title="logits" data-wiki-summary="softmax 之前的任意实数分数，用来比较各候选 token。" data-wiki-misconception="logits 已经是概率或正确率。">logits</a> 转成概率后，决定选概率最高的 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a>，还是按某种规则采样。</li></ul><p>“大”通常指<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>量、训练数据和训练计算的规模大，不代表模型必然正确，也不代表所有<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>都保存了一条可直接查询的事实。</p><h2 id="训练与推理不是一回事" tabindex="-1">训练与推理不是一回事 <a class="header-anchor" href="#训练与推理不是一回事" aria-label="Permalink to &quot;训练与推理不是一回事&quot;">​</a></h2><p><strong>训练</strong>时有参考答案。模型预测下一个 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a>，计算预测与答案的差距，再用<a href="/LLMTrain/05-速查表/术语速查#term-gradient" class="wiki-term" data-wiki-title="gradient" data-wiki-summary="loss 对各参数的局部变化率，指出当前附近怎样调整会改变 loss。" data-wiki-misconception="梯度直接给出了全局最优答案。">梯度</a>更新<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>。</p><p><strong><a href="/LLMTrain/05-速查表/术语速查#term-inference" class="wiki-term" data-wiki-title="inference" data-wiki-summary="使用训练好的参数，根据输入计算预测或生成结果。" data-wiki-misconception="推理阶段通常会继续更新模型权重。">推理</a></strong>时通常不更新<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>。模型根据当前<a href="/LLMTrain/05-速查表/术语速查#term-context" class="wiki-term" data-wiki-title="context" data-wiki-summary="模型本次计算能够看到的 token 序列。" data-wiki-misconception="放进上下文的信息已经永久写入模型参数。">上下文</a>反复预测和追加 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a>。把一段资料放入<a href="/LLMTrain/05-速查表/术语速查#term-context" class="wiki-term" data-wiki-title="context" data-wiki-summary="模型本次计算能够看到的 token 序列。" data-wiki-misconception="放进上下文的信息已经永久写入模型参数。">上下文</a>能临时影响回答，但不等于模型已经把资料训练进<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>。</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:center;">有参考答案</th><th style="text-align:center;">更新<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a></th><th>常见输出</th></tr></thead><tbody><tr><td>训练</td><td style="text-align:center;">是</td><td style="text-align:center;">是</td><td><a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a>、<a href="/LLMTrain/05-速查表/术语速查#term-checkpoint" class="wiki-term" data-wiki-title="checkpoint" data-wiki-summary="训练过程保存的权重及恢复训练所需状态快照。" data-wiki-misconception="checkpoint 天然就是可直接上线的完整产品。">检查点</a></td></tr><tr><td>验证</td><td style="text-align:center;">是</td><td style="text-align:center;">否</td><td>验证 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a>、指标</td></tr><tr><td><a href="/LLMTrain/05-速查表/术语速查#term-inference" class="wiki-term" data-wiki-title="inference" data-wiki-summary="使用训练好的参数，根据输入计算预测或生成结果。" data-wiki-misconception="推理阶段通常会继续更新模型权重。">推理</a></td><td style="text-align:center;">通常没有</td><td style="text-align:center;">否</td><td>生成文本</td></tr></tbody></table><h2 id="它不是什么" tabindex="-1">它不是什么 <a class="header-anchor" href="#它不是什么" aria-label="Permalink to &quot;它不是什么&quot;">​</a></h2><ul><li>不是实时更新的百科数据库，知识可能过时或混杂。</li><li>不是每次都按固定规则查到唯一答案的普通程序。</li><li>不能仅凭流畅语气证明事实正确。</li><li>是否具有意识属于哲学和科学争议，不能从“会对话”直接推出结论。</li></ul><h2 id="动手任务" tabindex="-1">动手任务 <a class="header-anchor" href="#动手任务" aria-label="Permalink to &quot;动手任务&quot;">​</a></h2><p>以提示“天空通常是”为例，写出你认为可能的 5 个后续 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a>，并让总概率加起来等于 1。概率是模型的候选分布，不等于事实投票。</p><h2 id="今日验收" tabindex="-1">今日验收 <a class="header-anchor" href="#今日验收" aria-label="Permalink to &quot;今日验收&quot;">​</a></h2><ol><li><a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>与 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 有什么区别？</li><li>为什么多轮对话不等于模型在持续训练？</li><li>一次生成为什么可能每次不同？</li><li>“语言流畅”和“事实可靠”为什么不是同一指标？</li></ol><p>参考答案：<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>是模型内部被训练的数字，<a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 是输入输出单位；普通<a href="/LLMTrain/05-速查表/术语速查#term-inference" class="wiki-term" data-wiki-title="inference" data-wiki-summary="使用训练好的参数，根据输入计算预测或生成结果。" data-wiki-misconception="推理阶段通常会继续更新模型权重。">推理</a>不更新<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>；采样会引入随机性；训练目标主要约束序列预测，不自动提供事实核验。</p><p>下一课：<a href="./D02-文字如何变成数字">D02：文字如何变成数字</a></p>',15))])}const f=e(s,[["render",k]]);export{L as __pageData,f as default};
